## services/marketDataService.ts

Updated `generateMockChain` to calculate Greeks using approximations based on moneyness and time to expiration.

```typescript
import { MarketData, ExpirationDate, OptionContract } from '../types';
import { API_KEY } from '../constants';

// --- Simulation Helper (Generates Chain based on Stock Price) ---
const generateMockChain = (currentPrice: number): ExpirationDate[] => {
  const expirations = [7, 14, 30, 45, 60, 90]; // Days to expiration

  return expirations.map((dte) => {
    const today = new Date();
    const expDate = new Date(today.setDate(today.getDate() + dte));
    const dateStr = expDate.toISOString().split('T')[0];

    const strikes: OptionContract[] = [];
    const minStrike = Math.floor(currentPrice * 0.8);
    const maxStrike = Math.ceil(currentPrice * 1.1);

    const interval = currentPrice > 200 ? 5 : (currentPrice > 50 ? 1 : 0.5);

    for (let s = minStrike; s <= maxStrike; s += interval) {
      const distance = s - currentPrice; // Strike - Price. Positive if ITM for Put.
      // For Puts: ITM if Strike > Price. OTM if Strike < Price.
      // However, distance calculation above:
      // If s=90, p=100, dist=-10 (OTM Put)
      // If s=110, p=100, dist=10 (ITM Put)

      let timeValue = (currentPrice * 0.05) * Math.sqrt(dte / 365); 
      let intrinsic = Math.max(0, s - currentPrice); // Put Intrinsic = Strike - Price

      // Decay time value as we get further from ATM
      const moneyness = Math.abs(s - currentPrice) / currentPrice;
      timeValue = timeValue * Math.exp(-moneyness * 10);

      const theoreticalPrice = intrinsic + timeValue;
      const bid = Math.max(0.01, Math.round((theoreticalPrice * 0.95) * 100) / 100);
      const ask = Math.max(0.01, Math.round((theoreticalPrice * 1.05) * 100) / 100);

      // --- Greeks Simulation (Black-Scholes Approximations for Puts) ---

      // Delta: -0.5 ATM, -> -1.0 ITM, -> 0 OTM
      // Approximate using logistic function of moneyness scaled by vol/time
      // Simple heuristic:
      let delta = -0.5 + (s - currentPrice) / (currentPrice * 0.2); 
      delta = Math.max(-1, Math.min(0, delta));

      // Gamma: Highest ATM, bell curve shape
      // Heuristic: Gaussian based on distance
      let gamma = (1 / (currentPrice * 0.2 * Math.sqrt(dte/365))) * Math.exp(-0.5 * Math.pow((s-currentPrice)/(currentPrice*0.05), 2));
      gamma = Math.max(0, Math.min(0.1, gamma));

      // Theta: Time decay, negative, highest ATM
      let theta = -1 * (currentPrice * 0.1) / Math.sqrt(dte) * Math.exp(-moneyness * 5);

      // Vega: Sensitivity to Vol, highest ATM
      let vega = 0.5 * currentPrice * Math.sqrt(dte/365) * Math.exp(-moneyness * 5);

      strikes.push({
        strike: s,
        bid,
        ask,
        last: bid,
        vol: Math.floor(Math.random() * 1000),
        delta: parseFloat(delta.toFixed(3)),
        gamma: parseFloat(gamma.toFixed(4)),
        theta: parseFloat(theta.toFixed(3)),
        vega: parseFloat(vega.toFixed(3))
      });
    }

    return {
      date: dateStr,
      daysToExpiration: dte,
      strikes
    };
  });
};

type MarketCallback = (data: MarketData) => void;
type LogCallback = (message: string) => void;

export class MarketDataService {
  private subscribers: Map<string, Set<MarketCallback>> = new Map();
  private logSubscribers: Set<LogCallback> = new Set();
  private currentTicker: string | null = null;

  // State
  public isSimulationMode: boolean = false;
  private pollingInterval: number | null = null;

  // Cache
  private lastMarketData: MarketData | null = null;

  constructor() {
    // Initial setup
  }

  // --- Logging System ---
  public subscribeLogs(callback: LogCallback): () => void {
    this.logSubscribers.add(callback);
    return () => this.logSubscribers.delete(callback);
  }

  private log(msg: string) {
    const timestamp = new Date().toLocaleTimeString();
    const formattedMsg = `[${timestamp}] ${msg}`;
    console.log(formattedMsg);
    this.logSubscribers.forEach(cb => cb(formattedMsg));
  }

  private error(msg: string, err?: any) {
     const timestamp = new Date().toLocaleTimeString();
     const formattedMsg = `[${timestamp}] ERROR: ${msg} ${err ? JSON.stringify(err) : ''}`;
     console.error(formattedMsg);
     this.logSubscribers.forEach(cb => cb(formattedMsg));
  }

  // --- Public Subscription API ---
  public subscribe(ticker: string, callback: MarketCallback): () => void {
    const upperTicker = ticker.toUpperCase();

    if (!this.subscribers.has(upperTicker)) {
      this.subscribers.set(upperTicker, new Set());
    }
    this.subscribers.get(upperTicker)?.add(callback);

    if (this.currentTicker !== upperTicker) {
      this.currentTicker = upperTicker;
      this.log(`Switched ticker to ${upperTicker}. Starting REST Polling...`);
      this.startPolling();
    } else if (this.lastMarketData) {
       callback(this.lastMarketData);
    }

    return () => {
      const subs = this.subscribers.get(upperTicker);
      subs?.delete(callback);
      if (subs?.size === 0) {
        this.subscribers.delete(upperTicker);
        if (this.subscribers.size === 0) {
            this.stopPolling();
        }
      }
    };
  }

  // --- REST Polling Logic ---

  private stopPolling() {
    if (this.pollingInterval) {
      clearInterval(this.pollingInterval);
      this.pollingInterval = null;
    }
    this.currentTicker = null;
  }

  private startPolling() {
    if (this.pollingInterval) clearInterval(this.pollingInterval);

    // Initial Fetch
    this.fetchPrice();

    // Poll every 15 seconds (4 calls/minute) to respect Free Tier limit of 5 calls/min
    this.pollingInterval = window.setInterval(() => {
      this.fetchPrice();
    }, 15000); 
  }

  private async fetchPrice() {
    if (!this.currentTicker) return;

    try {
      this.log(`Fetching price for ${this.currentTicker}...`);

      // Try fetching Previous Close (Available on Free Tier)
      // Endpoint: /v2/aggs/ticker/{ticker}/prev
      const url = `https://api.polygon.io/v2/aggs/ticker/${this.currentTicker}/prev?adjusted=true&apiKey=${API_KEY}`;

      const response = await fetch(url);
      const data = await response.json();

      if (data.status === 'OK' && data.results && data.results.length > 0) {
        const result = data.results[0];
        const price = result.c; // Close price

        this.isSimulationMode = false;
        this.log(`Price Received: $${price} (Prev Close)`);

        this.publishData(this.currentTicker, price);
      } else {
        // Fallback or Error
        if (data.status === 'ERROR') {
             this.error(`API Error: ${data.error || 'Unknown'}`);
        } else {
            this.log(`No data returned for ${this.currentTicker}. Response status: ${data.status}`);
        }

        // If API fails (e.g., rate limit), warn user but maybe don't simulate immediately unless needed
        if (!this.lastMarketData) {
            this.log("Falling back to simulation due to API failure.");
            this.startSimulation();
        }
      }
    } catch (e) {
      this.error("Fetch failed", e);
      this.startSimulation();
    }
  }

  private startSimulation() {
      this.isSimulationMode = true;
      let price = 450;
      if (this.currentTicker === 'TSLA') price = 240;
      else if (this.currentTicker === 'RIVN') price = 11;
      else if (this.currentTicker === 'AAPL') price = 180;

      // Add some random noise
      price = price * (1 + (Math.random() - 0.5) * 0.02);

      if (this.currentTicker) {
         this.publishData(this.currentTicker, price);
      }
  }

  private publishData(ticker: string, price: number) {
     const data: MarketData = {
          ticker: ticker,
          currentPrice: price,
          lastUpdated: Date.now(),
          chain: generateMockChain(price) // Generate chain based on fetched price
      };

      this.lastMarketData = data;
      const subs = this.subscribers.get(ticker.toUpperCase());
      if (subs) {
          subs.forEach(callback => callback(data));
      }
  }
}

export const marketService = new MarketDataService();
```

