## App.tsx

Updated calculation logic to populate `optionData` and rendered the `SelectedOptionDetails` component above the Gemini Insight box.

```tsx
import React, { useEffect, useState, useMemo, useRef } from 'react';
import { MarketData, TradeInputs, TradeCalculation } from './types';
import { DEFAULT_TARGET_APY, DEFAULT_TARGET_DISCOUNT, DEFAULT_TICKER } from './constants';
import { marketService } from './services/marketDataService';
import { InputPanel } from './components/InputPanel';
import { ResultsDisplay } from './components/ResultsDisplay';
import { ExpirationSelector } from './components/ExpirationSelector';
import { GeminiInsight } from './components/GeminiInsight';
import { GreeksPanel } from './components/GreeksPanel';
import { SelectedOptionDetails } from './components/SelectedOptionDetails';

const App: React.FC = () => {
  // --- State ---
  const [marketData, setMarketData] = useState<MarketData | null>(null);
  const [isSimulation, setIsSimulation] = useState(false);
  const [logs, setLogs] = useState<string[]>([]);
  const [showLogs, setShowLogs] = useState(true);

  const [inputs, setInputs] = useState<TradeInputs>({
    ticker: DEFAULT_TICKER,
    targetAPY: DEFAULT_TARGET_APY,
    targetDiscount: DEFAULT_TARGET_DISCOUNT,
    selectedDate: null,
  });

  const logsEndRef = useRef<HTMLDivElement>(null);

  // --- Effects ---

  // Subscribe to Logs
  useEffect(() => {
    const unsubscribeLogs = marketService.subscribeLogs((msg) => {
      setLogs(prev => [...prev.slice(-49), msg]); // Keep last 50 logs
    });
    return () => unsubscribeLogs();
  }, []);

  // Scroll to bottom of logs
  useEffect(() => {
    if (showLogs && logsEndRef.current) {
      logsEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [logs, showLogs]);

  // Connect to Market Data Service
  useEffect(() => {
    setInputs(prev => ({ ...prev, selectedDate: null }));
    setMarketData(null); 

    const unsubscribe = marketService.subscribe(inputs.ticker, (data) => {
      // Check simulation status from service
      setIsSimulation(marketService.isSimulationMode);

      setMarketData(prev => {
        if (prev && prev.ticker === data.ticker && prev.chain.length > 0) {
           return { ...prev, currentPrice: data.currentPrice, lastUpdated: data.lastUpdated };
        }
        return data;
      });
    });

    return () => {
      unsubscribe();
    };
  }, [inputs.ticker]);

  // --- Calculation Logic ---
  const calculation: TradeCalculation | null = useMemo(() => {
    if (!marketData || !inputs.selectedDate) return null;

    const currentPrice = marketData.currentPrice;
    const rawStrike = currentPrice * (1 - inputs.targetDiscount / 100);
    const calculatedStrike = Math.round(rawStrike * 2) / 2;
    const collateral = calculatedStrike * 100;

    const expirationData = marketData.chain.find(exp => exp.date === inputs.selectedDate);
    if (!expirationData) return null;

    const dte = expirationData.daysToExpiration;
    const requiredTotalCredit = collateral * (inputs.targetAPY / 100) * (dte / 365);

    const closestOption = expirationData.strikes.reduce((prev, curr) => {
      return (Math.abs(curr.strike - calculatedStrike) < Math.abs(prev.strike - calculatedStrike) ? curr : prev);
    });

    const actualPremiumPerShare = closestOption.bid; 
    const actualTotalCredit = actualPremiumPerShare * 100;
    const actualAPY = (actualTotalCredit / collateral) * (365 / dte) * 100;
    const netPurchasePrice = calculatedStrike - actualPremiumPerShare;

    return {
      calculatedStrike: closestOption.strike, 
      collateral: closestOption.strike * 100,
      dte,
      requiredTotalCredit,
      actualTotalCredit,
      actualAPY,
      netPurchasePrice,
      isTargetMet: actualTotalCredit >= requiredTotalCredit,
      actualPremiumPerShare,
      optionData: closestOption,
      greeks: {
        delta: closestOption.delta,
        gamma: closestOption.gamma,
        theta: closestOption.theta,
        vega: closestOption.vega
      }
    };

  }, [marketData, inputs.selectedDate, inputs.targetAPY, inputs.targetDiscount]);


  // --- Render ---
  return (
    <div className="min-h-screen bg-slate-950 text-slate-200 pb-80">

      {/* Header */}
      <header className="bg-slate-900 border-b border-slate-800 sticky top-0 z-50 backdrop-blur-md bg-opacity-80">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-3">
             <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white font-bold font-mono">
               CP
             </div>
             <h1 className="text-xl font-bold tracking-tight text-white hidden sm:block">
               CSP <span className="text-indigo-400">Validator</span>
             </h1>
          </div>

          {/* Status & Ticker */}
          <div className="flex items-center space-x-4">

            {/* Connection Badge */}
            <div className={`flex items-center px-3 py-1 rounded-full text-xs font-bold border ${isSimulation ? 'bg-amber-900/20 text-amber-500 border-amber-900/50' : 'bg-blue-900/20 text-blue-400 border-blue-900/50'}`}>
               <span className={`w-2 h-2 rounded-full mr-2 ${isSimulation ? 'bg-amber-500' : 'bg-blue-400 animate-pulse'}`}></span>
               {isSimulation ? 'SIMULATION MODE' : 'REST POLLING (DELAYED)'}
            </div>

            <div className="flex items-center space-x-4 bg-slate-950 rounded-full px-4 py-1.5 border border-slate-800">
              <span className="font-mono font-bold text-white uppercase">{inputs.ticker}</span>
              <span className="h-4 w-px bg-slate-700"></span>
              <span className={`font-mono ${!marketData ? 'animate-pulse' : ''}`}>
                {marketData ? `$${marketData.currentPrice.toFixed(2)}` : 'Connecting...'}
              </span>
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-8">

        {/* Intro */}
        <div className="max-w-3xl">
          <h2 className="text-3xl font-bold text-white mb-2">Validate your trade.</h2>
          <p className="text-slate-400">
            Check if a Cash-Secured Put meets your annualized return targets.
            {isSimulation && <span className="text-amber-500 block mt-1 font-semibold">⚠ Displaying simulated data because the API connection failed. Check debug logs below.</span>}
          </p>
        </div>

        {/* Inputs */}
        <InputPanel inputs={inputs} setInputs={setInputs} />

        {/* Results */}
        {marketData && (
          <div className="bg-slate-900/50 p-6 rounded-xl border border-slate-800/50">
             <ExpirationSelector 
               chain={marketData.chain} 
               selectedDate={inputs.selectedDate} 
               onSelect={(date) => setInputs(prev => ({ ...prev, selectedDate: date }))}
             />

             {/* Greeks Panel */}
             {calculation && calculation.greeks && (
                 <GreeksPanel greeks={calculation.greeks} />
             )}

             <ResultsDisplay calculation={calculation} inputs={inputs} />

             {/* Option Details Panel */}
             {calculation && calculation.optionData && inputs.selectedDate && (
                 <SelectedOptionDetails 
                    ticker={inputs.ticker}
                    date={inputs.selectedDate}
                    data={calculation.optionData}
                 />
             )}

             {calculation && marketData && (
               <GeminiInsight 
                 inputs={inputs} 
                 calculation={calculation} 
                 currentPrice={marketData.currentPrice} 
               />
             )}
          </div>
        )}
      </main>

      {/* Debug Logs Console */}
      <div className={`fixed bottom-0 left-0 right-0 bg-slate-950 border-t border-slate-800 transition-all duration-300 ${showLogs ? 'h-64' : 'h-10'}`}>
        <div 
          className="flex items-center justify-between px-4 h-10 bg-slate-900 cursor-pointer hover:bg-slate-800"
          onClick={() => setShowLogs(!showLogs)}
        >
           <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider flex items-center gap-2">
             <span className="w-2 h-2 rounded-full bg-slate-500"></span>
             System Logs & Debugger (Polygon.io REST)
           </h3>
           <span className="text-slate-500 text-xs">{showLogs ? 'Hide' : 'Show'}</span>
        </div>

        {showLogs && (
          <div className="h-52 overflow-y-auto p-4 font-mono text-xs text-slate-300 space-y-1">
            {logs.length === 0 && <span className="text-slate-600 italic">No logs yet...</span>}
            {logs.map((log, i) => (
              <div key={i} className={`border-l-2 pl-2 ${log.includes('ERROR') ? 'border-rose-500 text-rose-300' : (log.includes('TX') || log.includes('RX')) ? 'border-indigo-500 text-slate-400' : 'border-emerald-500'}`}>
                {log}
              </div>
            ))}
            <div ref={logsEndRef} />
          </div>
        )}
      </div>
    </div>
  );
};

export default App;
